  private async getMsPool(): Promise<sql.ConnectionPool> {
    // Nếu đã có pool instance và nó còn sống thì trả về luôn
    if (this.pool?.connected) {
      return this.pool;
    }

    // Nếu pool disconnected, cố gắng reconnect
    if (this.pool && !this.pool.connected && !this.pool.connecting) {
      console.warn('[MSSQL] Pool disconnected, attempting to reconnect...');
      try {
        await this.pool.connect();
        return this.pool;
      } catch (err) {
        console.error('[MSSQL] Reconnect failed, creating new pool...', err);
        try {
          await this.pool.close();
        } catch { }
        this.pool = null as any;
      }
    }

    // Nếu chưa có hoặc reconnect failed, tạo pool mới
    this.pool = await getMssqlPool(this.configService);

    if (!this.pool.connected) {
      throw new Error('MSSQL pool not connected');
    }

    return this.pool;
  }
  // Helper function để normalize commanders - đảm bảo luôn là mảng đơn giản
  private normalizeCommanders(commanders: any): string[] {
    if (!commanders) return [];

    // Nếu là string, parse nó
    let parsed: any = commanders;
    if (typeof commanders === 'string') {
      try {
        parsed = JSON.parse(commanders);
      } catch {
        return [];
      }
    }

    // Nếu không phải array, trả về mảng rỗng
    if (!Array.isArray(parsed)) {
      return [];
    }

    // Flatten mảng lồng nhau và chuyển tất cả thành string
    const flatten = (arr: any[]): string[] => {
      const result: string[] = [];
      for (const item of arr) {
        if (Array.isArray(item)) {
          result.push(...flatten(item));
        } else if (item != null && item !== '') {
          result.push(String(item));
        }
      }
      return result;
    };

    const flattened = flatten(parsed);

    // Loại bỏ duplicate và trả về
    return [...new Set(flattened)];
  };

  // Normalize signer input to a flat list of string IDs
  private normalizeSignerIds(value: any): string[] {
    if (value === null || value === undefined || value === '') return [];

    const acc: string[] = [];
    const add = (v: any) => {
      if (v === null || v === undefined || v === '') return;
      if (Array.isArray(v)) {
        v.forEach(add);
        return;
      }
      if (typeof v === 'string') {
        const trimmed = v.trim();
        if (!trimmed) return;
        if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
          try {
            const parsed = JSON.parse(trimmed);
            add(parsed);
            return;
          } catch {
            // ignore and treat as single value
          }
        }
        acc.push(trimmed);
        return;
      }
      if (typeof v === 'number') {
        acc.push(String(v));
        return;
      }
      if (typeof v === 'object') {
        const id = (v as any).userId ?? (v as any).id ?? (v as any)._id ?? (v as any).value;
        if (id !== null && id !== undefined && id !== '') {
          acc.push(String(id));
        }
        return;
      }
      acc.push(String(v));
    };

    add(value);
    return [...new Set(acc)];
  }
