  async getAssignmentDeadline(documentId: string, receiverId: string): Promise<Date | null> {
    const request = this.pool.request();
    request.input('documentId', documentId);
    request.input('receiver', receiverId);
    const result = await request.query(`
      SELECT TOP 1 deadline 
      FROM (
        SELECT deadline, created_at
        FROM ${this.dbname}.dbo.incomming_assignment 
        WHERE document_id = @documentId AND receiver = @receiver AND deadline IS NOT NULL
        
        UNION ALL
        
        SELECT deadline, created_at
        FROM ${this.dbname}.dbo.audit
        WHERE document_id = @documentId AND receiver = @receiver AND deadline IS NOT NULL
      ) t
      ORDER BY t.created_at DESC
    `);
    if (result.recordset.length > 0 && result.recordset[0].deadline) {
      return new Date(result.recordset[0].deadline);
    }
    return null;
  }

  async getAssignmentDetail(
    documentId: string,
    receiverId: string,
  ): Promise<{ deadline: Date | null; roleProcess: string | null; assignerUserId: string | null } | null> {
    const request = this.pool.request();
    request.input('documentId', documentId);
    request.input('receiver', receiverId);
    const result = await request.query(`
      SELECT TOP 1 
        ia.deadline, 
        ia.role_process as roleProcess,
        a.user_id as assignerUserId
      FROM ${this.dbname}.dbo.incomming_assignment ia
      LEFT JOIN ${this.dbname}.dbo.audit a ON a.id = ia.last_audit_id
      WHERE ia.document_id = @documentId AND ia.receiver = @receiver
      ORDER BY ia.created_at DESC
    `);
    if (result.recordset.length > 0) {
      const row = result.recordset[0];
      return {
        deadline: row.deadline ? new Date(row.deadline) : null,
        roleProcess: row.roleProcess || null,
        assignerUserId: row.assignerUserId || null,
      };
    }
    return null;
  }

  async getAssignedUsersByLeader(
    documentId: string,
    leaderUserId: string,
  ): Promise<string[]> {
    const request = this.pool.request();
    request.input('documentId', documentId);
    request.input('leaderUserId', leaderUserId);
    const result = await request.query(`
      SELECT DISTINCT receiver 
      FROM ${this.dbname}.dbo.audit 
      WHERE document_id = @documentId 
        AND (user_id = @leaderUserId OR created_by = @leaderUserId)
        AND (
          action_code = 'PHAN_CONG' 
          OR (details LIKE '%"phanCong":true%' OR details LIKE '%"phanCong":"true"%')
        )
        AND receiver IS NOT NULL
    `);
    return result.recordset.map((r: any) => r.receiver);
  }

  async isIncomingDocumentCompleted(documentId: string): Promise<boolean> {
    const request = this.pool.request();
    request.input('documentId', documentId);
    const result = await request.query(`
      SELECT TOP 1 is_completed_doc AS isCompletedDoc, current_stage_status AS currentStageStatus
      FROM ${this.dbname}.dbo.incomming_current_state 
      WHERE document_id = @documentId
    `);
    if (result.recordset.length > 0) {
      const row = result.recordset[0];
      return row.isCompletedDoc === 1 || row.isCompletedDoc === true || row.currentStageStatus === 'HOAN_THANH_VAN_BAN';
    }
    return false;
  }

  async listOpenWorkItemsByIds(ids: string[]): Promise<any[]> {
    if (!ids.length) return [];

    const request = this.pool.request();
    request.input('idsJson', sql.NVarChar(sql.MAX), JSON.stringify(ids));

    const sqlQuery = `
      SELECT document_id, id, node_id, role, assignee_user_id, node_type, state
      FROM work_items WITH (NOLOCK)
      WHERE document_id IN (SELECT value FROM OPENJSON(@idsJson))
        AND state = 'open'
    `;

    const result = await request.query<WorkItemRow[]>(sqlQuery);

    return result.recordset.map((r) => ({
      id: String(r.id),
      documentId: r.document_id,
      nodeId: r.node_id,
      role: r.role,
      assigneeUserId: r.assignee_user_id,
      nodeType: r.node_type,
      state: r.state,
    }));
  }

