  async getWorkItemv2(documentIds: string[], workItemId: string): Promise<any[] | null> {
    if (!documentIds || documentIds.length === 0) return null;

    const request = this.pool.request();
    documentIds.forEach((id, idx) => request.input(`id${idx}`, id));
    request.input('workItemId', workItemId);

    const inClause = documentIds.map((_, idx) => `@id${idx}`).join(', ');
    const sql = `
      SELECT TOP 1 id, document_id, node_id, role, assignee_user_id, node_type, state
      FROM work_items
      WHERE document_id IN (${inClause}) AND id = @workItemId
    `;

    const result = await request.query<WorkItemRow[]>(sql);
    if (!result.recordset.length) return null;

    return result.recordset.map((x) => ({
      id: String(x.id),
      documentId: x.document_id,
      nodeId: x.node_id,
      role: x.role,
      assigneeUserId: x.assignee_user_id,
      nodeType: x.node_type,
      state: x.state,
    }));
  }

