  async getAuditByCondition(
    filter: AuditFilter,
    or: AuditFilter,
    select: string[] = ['*'],
  ): Promise<any[]> {

    const request = this.pool.request();

    const andConditions: string[] = [];
    const orConditions: string[] = [];

    // ================= AND GROUP =================
    if (filter.documentId) {
      andConditions.push('a.document_id = @documentId');
      request.input('documentId', filter.documentId);
    }

    if (filter.role) {
      andConditions.push('a.role = @role');
      request.input('role', filter.role);
    }

    if (filter.userId) {
      andConditions.push('a.user_id = @userId');
      request.input('userId', filter.userId);
    }

    if (filter.actionCode) {
      andConditions.push('a.action_code = @actionCode');
      request.input('actionCode', filter.actionCode);
    }

    if (filter.fromNodeId) {
      andConditions.push('a.from_node_id = @fromNodeId');
      request.input('fromNodeId', filter.fromNodeId);
    }

    if (filter.toNodeId) {
      andConditions.push('a.to_node_id = @toNodeId');
      request.input('toNodeId', filter.toNodeId);
    }

    if (filter.receiver) {
      andConditions.push('a.receiver = @receiver');
      request.input('receiver', filter.receiver);
    }

    if (filter.typeDocument) {
      andConditions.push('a.type_document = @typeDocument');
      request.input('typeDocument', filter.typeDocument);
    }

    // ================= OR GROUP =================
    if (or?.createdBy) {
      orConditions.push('a.created_by = @createdBy');
      request.input('createdBy', or.createdBy);
    }

    if (or?.userId) {
      orConditions.push('a.user_id = @orUserId');
      request.input('orUserId', or.userId);
    }

    if (or?.receiver) {
      orConditions.push('a.receiver = @orReceiver');
      request.input('orReceiver', or.receiver);
    }

    // ================= BUILD WHERE =================
    let whereClause = '';

    if (andConditions.length && orConditions.length) {
      whereClause = `WHERE (${andConditions.join(' AND ')}) OR (${orConditions.join(' AND ')})`;
    } else if (andConditions.length) {
      whereClause = `WHERE ${andConditions.join(' AND ')}`;
    } else if (orConditions.length) {
      whereClause = `WHERE ${orConditions.join(' AND ')}`;
    }

    // ================= SELECT WHITELIST =================
    const allowedColumns = new Set([
      'id', 'document_id', 'from_node_id', 'to_node_id', 'user_id', 'display_name',
      'role', 'action_code', 'time', 'created_by', 'receiver', 'receiver_unit',
      'details', 'created_at', 'updated_at'
    ]);

    const selectClause = select
      .filter(col => allowedColumns.has(col))
      .map(col => `a.${col}`)
      .join(', ') || 'a.*';

    const sql = `
    SELECT ${selectClause}
    FROM ${this.dbname}.dbo.audit a
    ${whereClause}
    ORDER BY a.time ASC, a.created_at ASC
  `;

    const result = await request.query(sql);
    return result.recordset;
  }




