  async listUserProcessedDocuments(
    userId: string,
    opts: { since?: string; limit?: number } = {},
  ): Promise<any[]> {
    const request = this.pool.request();
    request.input('user_id', userId);

    const whereClauses = ['user_id = @user_id'];
    if (opts.since) {
      whereClauses.push('time >= @since');
      request.input('since', new Date(opts.since));
    }

    // SQL Server không có GROUP_CONCAT/SUBSTRING_INDEX, dùng STRING_AGG + TOP
    const limitClause = opts.limit ? `TOP(${Number(opts.limit)})` : '';
    const sql = `
      SELECT ${limitClause} document_id,
            MAX(time) AS last_time,
            (SELECT TOP 1 action_code
              FROM audit a2
              WHERE a2.document_id = a1.document_id
              ORDER BY time DESC) AS last_action
      FROM audit a1
      WHERE ${whereClauses.join(' AND ')}
      GROUP BY document_id
      ORDER BY last_time DESC
    `;

    const result = await request.query(sql);
    return result.recordset.map((x) => ({
      documentId: x.document_id,
      lastAction: x.last_action,
      lastTime: x.last_time instanceof Date ? x.last_time.toISOString() : x.last_time,
    }));
  }

  // Hàm dùng chung để lấy role của user (MongoDB giữ nguyên)
  async getUserRole(
    userId: string,
    processKey: string = 'PHOIHOP_NHANDEBIET',
  ) {
    if (!userId) {
      return { roles: [''], userRoles: [] };
    }

    const cacheKey = `${String(userId).trim()}:${String(processKey || '').trim()}`;
    const redisCacheKey = `user-role:${cacheKey}`;
    const cached = await this.getRedisBackedCache<{ roles: string[]; userRoles: string[] }>(
      this.userRoleCache,
      redisCacheKey,
      this.USER_ROLE_CACHE_TTL,
    );
    if (cached) {
      return cached;
    }

    const userRolesSet = new Set<string>();

    const pool = this.getPool();

    const directRolesPromise = pool.request()
      .input('userId', userId)
      .input('processKey', processKey)
      .query(`
        SELECT rp.role_code AS roleCode
        FROM ${this.dbname}.dbo.roles_process_users rpu
        INNER JOIN ${this.dbname}.dbo.roles_process rp
          ON rp.id = rpu.role_id
        WHERE rpu.user_id = @userId
          AND rp.process_key = @processKey
          AND rp.is_active = 1
      `);

    const groupRolesPromise = pool.request()
      .input('userId', userId)
      .input('processKey', processKey)
      .query(`
        SELECT DISTINCT rp.role_code AS roleCode
        FROM ${this.dbname}.dbo.roles_process_groups rpg
        INNER JOIN ${this.dbname}.dbo.roles_process rp
          ON rp.id = rpg.role_id
        INNER JOIN ${this.dbname}.dbo.user_group_users ugu
          ON ugu.group_user_id = rpg.group_id
        WHERE ugu.user_id = @userId
          AND rp.process_key = @processKey
          AND rp.is_active = 1
      `);

    const [directRolesRes, groupRolesRes] = await Promise.all([
      directRolesPromise,
      groupRolesPromise,
    ]);

    for (const row of directRolesRes.recordset || []) {
      if (row?.roleCode) {
        userRolesSet.add(String(row.roleCode));
      }
    }

    for (const row of groupRolesRes.recordset || []) {
      if (row?.roleCode) {
        userRolesSet.add(String(row.roleCode));
      }
    }

    const userRoles = Array.from(userRolesSet);

    const result = {
      roles: userRoles.length ? userRoles : [''],
      userRoles,
    };

    await this.setRedisBackedCache(
      this.userRoleCache,
      redisCacheKey,
      result,
      this.USER_ROLE_CACHE_TTL,
    );

    return result;
  }

  async getUserRolesFromGroups(userId: string) {
    if (!userId) {
      return { roles: [], byProcess: {} };
    }

    const pool = await this.getPool();
    const request = pool.request();
    request.input('userId', userId);

    const sql = `
      SELECT 
        gu.roles,
        gu.roles_dynamic
      FROM ${this.dbname}.dbo.user_group_users ugu
      JOIN ${this.dbname}.dbo.group_users gu 
        ON gu.id = ugu.group_user_id
      WHERE ugu.user_id = @userId
        AND gu.status = 1
    `;

    const rs = await request.query(sql);

    const allRoles = new Set<string>();
    const byProcess: Record<string, string[]> = {};

    for (const row of rs.recordset) {
      // ===== STATIC ROLES =====
      if (row.roles) {
        try {
          const roles: unknown = JSON.parse(row.roles);
          if (Array.isArray(roles)) {
            for (const r of roles) {
              if (typeof r === 'string' && r.trim()) {
                allRoles.add(r.trim());
              }
            }
          }
        } catch {
          // JSON lỗi → bỏ qua, không crash
        }
      }

      // ===== DYNAMIC ROLES =====
      if (row.roles_dynamic) {
        try {
          const dyn: unknown = JSON.parse(row.roles_dynamic);
          if (Array.isArray(dyn)) {
            for (const item of dyn) {
              if (
                item &&
                typeof item.processKey === 'string' &&
                typeof item.roleCode === 'string'
              ) {
                const pk = item.processKey.trim();
                const role = item.roleCode.trim();

                if (!pk || !role) continue;

                allRoles.add(role);

                if (!byProcess[pk]) byProcess[pk] = [];
                if (!byProcess[pk].includes(role)) {
                  byProcess[pk].push(role);
                }
              }
            }
          }
        } catch {
          // JSON lỗi → bỏ qua
        }
      }
    }
    const finalRows = this.normalizeRoleCodes(allRoles);
    return {
      roles: [...finalRows],
      byProcess,
    };
  }

  normalizeRoleCodes(rawRoles: Iterable<string> = []): string[] {
    const set = new Set<string>();
    for (const raw of rawRoles) {
      if (!raw || typeof raw !== 'string') continue;
      const role = raw.trim();
      const match = role.match(
        /^[0-9a-fA-F-]{36}_(.+)$/
      );
      const roleCode = match ? match[1] : role;
      if (roleCode) set.add(roleCode);
    }
    return [...set];
  }

