  async getUserOrgUnitInfo(userId: string): Promise<{
    unitId: string | null;
    mpath: string | null;
    isCuc: boolean;
    isPhong: boolean;
  }> {
    if (!userId) {
      return { unitId: null, mpath: null, isCuc: false, isPhong: false };
    }

    const pool = await this.getPool();
    const req = pool.request();
    req.input('userId', userId);

    const sql = `
      SELECT TOP 1 
        ou.id,
        ou.mpath
      FROM ${this.dbname}.dbo.users u
      JOIN ${this.dbname}.dbo.organization_units ou 
        ON ou.id = u.parent
      WHERE u.id = @userId
        AND ou.status = 1
    `;

    const rs = await req.query(sql);
    const row = rs.recordset[0];

    if (!row) {
      return { unitId: null, mpath: null, isCuc: false, isPhong: false };
    }

    const mpath: string = row.mpath || '';
    const isCuc = !!mpath && !mpath.includes('/');
    const isPhong = !!mpath && mpath.includes('/');

    return {
      unitId: row.id,
      mpath,
      isCuc,
      isPhong,
    };
  }

  async getUserRoleWithName(
    userId: string,
    processKey: string = 'PHOIHOP_NHANDEBIET',
  ) {
    if (!userId) {
      return { roles: [''], userRoles: [] };
    }

    // Map roleCode -> name từ role_feature
    const roleNameMap = new Map<string, string>();
    const userRolesSet = new Set<string>();

    // 1️⃣ Lấy role trực tiếp từ role_feature (user nằm trong roles.users)
    const roleDoc = await this.roleFeatureRepository.findOne({
      where: { processKey },
      select: { roles: true },
    });

    if (roleDoc?.roles && Array.isArray(roleDoc.roles)) {
      for (const r of roleDoc.roles) {
        if (r?.roleCode) {
          roleNameMap.set(r.roleCode, r.name || r.roleCode);
          if (Array.isArray(r.users) && r.users.includes(userId)) {
            userRolesSet.add(r.roleCode);
          }
        }
      }
    }

    // 2️⃣ Lấy role từ nhóm người dùng qua roles_dynamic
    // Tìm nhóm user thuộc về → đọc roles_dynamic → lọc theo processKey
    const pool = this.getPool();
    const request = pool.request();
    request.input('userId', userId);
    const groupsRes = await request.query(`
      SELECT gu.roles_dynamic
      FROM ${this.dbname}.dbo.user_group_users ugu
      JOIN ${this.dbname}.dbo.group_users gu
        ON gu.id = ugu.group_user_id
      WHERE ugu.user_id = @userId
        AND gu.status = 1
    `);

    for (const row of groupsRes.recordset) {
      if (!row.roles_dynamic) continue;
      try {
        const rolesDynamic = typeof row.roles_dynamic === 'string'
          ? JSON.parse(row.roles_dynamic)
          : row.roles_dynamic || [];
        if (Array.isArray(rolesDynamic)) {
          for (const rd of rolesDynamic) {
            if (rd?.processKey === processKey && rd?.roleCode) {
              userRolesSet.add(rd.roleCode);
            }
          }
        }
      } catch {
        // JSON lỗi → bỏ qua
      }
    }

    const userRoles = Array.from(userRolesSet)
      .map((roleCode) => ({
        roleCode,
        name: roleNameMap.get(roleCode) || roleCode,
      }))
      .filter((r) => r.roleCode);

    const roleCodes = userRoles.map((r) => r.roleCode);
    return {
      roles: roleCodes.length ? roleCodes : [''],
      userRoles, // Array of { roleCode, name }
    };
  }

