  async isTaskParticipant(taskId: string, userId: string): Promise<boolean> {
    if (!taskId || !userId) return false;
    const sql = `
      SELECT TOP 1 1
      FROM task t
      LEFT JOIN task_users tu ON tu.task_id = t.id AND LOWER(LTRIM(RTRIM(tu.process_id))) = LOWER(LTRIM(RTRIM(@userId))) AND tu.type = 1
      WHERE t.id = @taskId 
        AND (
          LOWER(LTRIM(RTRIM(t.created_by))) = LOWER(LTRIM(RTRIM(@userId)))
          OR tu.role IN ('director', 'assigner', 'supporter')
        )
    `;
    const request = this.pool.request();
    request.input('taskId', taskId);
    request.input('userId', userId.toString());
    const result = await request.query(sql);
    return result.recordset.length > 0;
  }

