  async createCommentv1(input: {
    documentId: string;
    parentId?: string | null;
    userId: string;
    userName: string;
    content: string;
    type?: string;
  }): Promise<any> {
    const newCommentId = String(Date.now());
    const request = this.pool.request();
    request.input('id', newCommentId);
    request.input('documentId', input.documentId);
    request.input('parentId', input.parentId || null);
    request.input('userId', input.userId);
    request.input('userName', input.userName);
    request.input('content', input.content);
    request.input('type', input.type || 'comment');

    await request.query(`
      INSERT INTO document_comments 
        (id, document_id, parent_id, user_id, user_name, content, type)
      VALUES 
        (@id, @documentId, @parentId, @userId, @userName, @content, @type)
    `);

    return this.getCommentById(newCommentId);
  }

  async createComment(input: {
    documentId: string;
    parentId?: string | null;
    userId: string;
    userName: string;
    content: string;
    type?: string;
    fileId?: string | null;
    isLeaderSuggestion?: boolean;
  }, tx?: any): Promise<any> {
    const newCommentId = String(Date.now());
    if (!tx) {
      await this.ensureConnected();
    }
    const request = tx ? tx.request() : this.pool.request();
    request.input('id', newCommentId);
    request.input('documentId', input.documentId);
    request.input('parentId', input.parentId || null);
    request.input('userId', input.userId);
    request.input('userName', input.userName);
    request.input('content', input.content);
    request.input('type', input.type || 'comment');
    request.input('fileId', JSON.stringify(input.fileId || []));
    request.input('isLeaderSuggestion', input.isLeaderSuggestion ?? false);

    try {
      await request.query(`
        INSERT INTO document_comments 
          (id, document_id, parent_id, user_id, user_name, content, type, fileId, is_leader_suggestion)
        VALUES 
          (@id, @documentId, @parentId, @userId, @userName, @content, @type, @fileId, @isLeaderSuggestion)
      `);
    } catch (err: any) {
      console.error('[MSSQLRepository.createComment] Error inserting comment:', {
        documentId: input.documentId,
        type: input.type,
        hasFileId: Array.isArray(input.fileId) ? input.fileId.length > 0 : Boolean(input.fileId),
        error: err?.message || err,
        stack: err?.stack,
      });
      throw err;
    }

    return this.getCommentById(newCommentId);
  }

