  // Helper
  private mapDocKeys(
    doc: any,
    aliases: Record<string, string> = {},
  ): Promise<any> {
    const result: any = {};
    for (const [dbKey, jsKey] of Object.entries(aliases)) {
      switch (dbKey) {
        case 'deadline':
          result[jsKey] = doc.deadline ?? '-';
          break;
        case 'user_deadline':
          result[jsKey] = doc.user_deadline ?? '-';
          break;
        case 'to_book_code':
          result[jsKey] = doc.to_book_code ?? '-';
          break;
        case 'book_document_name':
          result[jsKey] = doc.book_document_id ?? '-';
          break;
        case 'kanban_status':
          result[jsKey] = doc.status ?? '-';
          break;
        case 'processor_units_name':
          result[jsKey] = doc.processors ?? '-';
          break;
        case 'proposed_plan':
          result[jsKey] = '-';
          break;
        // case 'files':
        //   result[jsKey] = '-';
        //   break;
        default:
          if (doc[dbKey] !== undefined) {
            result[jsKey] = this.dateKeys.has(dbKey)
              ? this.normalizeDateValueDDMMYYYY(doc[dbKey])
              : doc[dbKey];
          } else {
            result[jsKey] = '-';
          }
      }
    }
    return result;
  }
  private mapDocKeysOutgoing(
    doc: any,
    aliases: Record<string, string> = {},
  ): Promise<any> {
    const result: any = {};
    for (const [dbKey, jsKey] of Object.entries(aliases)) {
      switch (dbKey) {
        case 'deadline':
          result[jsKey] = doc.deadline ?? '-';
          break;
        case 'user_deadline':
          result[jsKey] = doc.user_deadline ?? '-';
          break;
        default:
          if (doc[dbKey] !== undefined) {
            result[jsKey] = this.dateKeys.has(dbKey)
              ? this.normalizeDateValueDDMMYYYY(doc[dbKey])
              : doc[dbKey];
          }
      }
    }
    return result;
  }

