    // Join audit theo user
    let joinClause = ` INNER JOIN ( SELECT a.* FROM audit a INNER JOIN ( SELECT document_id, MAX(id) AS max_id FROM audit WHERE receiver = '${userId}' GROUP BY document_id ) t ON a.document_id = t.document_id AND a.id = t.max_id ) audit ON audit.document_id = incomming_documents.document_id `;
