    // 3. Build whereClause đúng
    let whereClause = where.length ? ' WHERE ' + where.join(' AND ') : '';
    whereClause += `AND incomming_documents.status = 1`;
    const limitNum = Math.min(Number(limit) || 20, 100);
    const pageNum = Math.max(Number(page) || 1, 1);
