  async getFilesByOutgoingDocumentIds(
    documentIds: string[],
    objectTypes?: string[],
  ): Promise<Record<string, any[]>> {
    if (!documentIds || documentIds.length === 0) return {};

    const request = this.pool.request();

    // Tạo placeholders cho documentIds
    const docPlaceholders = documentIds.map((id, i) => {
      request.input(`docId${i}`, id);
      return `@docId${i}`;
    }).join(',');

    let typeCondition = '';
    if (objectTypes && objectTypes.length > 0) {
      const typePlaceholders = objectTypes.map((type, i) => {
        request.input(`type${i}`, type);
        return `@type${i}`;
      }).join(',');
      typeCondition = `AND fr.object_type IN (${typePlaceholders})`;
    }

    const sql = `
      SELECT
        fr.object_id AS documentId,
        f.id AS fileId,
        f.file_name AS fileName,
        f.file_size AS fileSize,
        f.mime_type AS mimeType,
        f.file_path AS filePath,
        f.is_directory AS isDirectory,
        f.parent_id AS parentId,
        f.created_at AS createdAt,
        f.updated_at AS updatedAt,
        f.is_signed_file AS isSignedFile,
        f.number_of_signed_file AS numberOfSignedFile,
        f.created_by AS createdBy
      FROM ${this.dbname}.dbo.file_relations fr
      JOIN ${this.dbname}.dbo.files f ON fr.file_id = f.id
      WHERE fr.object_id IN (${docPlaceholders})
        ${typeCondition}
        AND f.status = 1
        AND (
          fr.object_type <> 'docDraft'
          OR NOT EXISTS (
            SELECT 1
            FROM ${this.dbname}.dbo.audit a WITH (NOLOCK)
            WHERE a.document_id = fr.object_id
            GROUP BY a.document_id
            HAVING
              MAX(CASE
                WHEN a.action_code IN ('TRA_LAI', 'THU_HOI', 'RETURN', 'RECALL', 'TRA_LAI_VT', 'TRA_LAI_TPSL', 'NO')
                  OR a.stage_status IN ('TRA_LAI', 'THU_HOI', 'TRA_LAI_VT', 'TRA_LAI_TPSL')
                THEN a.id ELSE 0
              END)
              >
              MAX(CASE
                WHEN a.action_code IN ('KY_NHAY_NOI_DUNG', 'KY_NHAY_THE_THUC', 'KY_SO', 'KY_BAN_HANH', 'DONG_DAU', 'paraphSigner', 'reportSigner', 'stampDoc')
                  OR a.stage_status IN ('DA_KY_NHAY', 'DA_KY', 'DA_KY_THE_THUC', 'DA_KY_BAN_HANH', 'DA_DONG_DAU')
                THEN a.id ELSE 0
              END)
          )
          OR ISNULL(f.is_signed_file, 0) = 0
          OR NOT EXISTS (
            SELECT 1
            FROM ${this.dbname}.dbo.file_relations fr0 WITH (NOLOCK)
            JOIN ${this.dbname}.dbo.files f0 WITH (NOLOCK) ON fr0.file_id = f0.id
            WHERE fr0.object_id = fr.object_id
              AND fr0.object_type = 'docDraft'
              AND fr0.status = 1
              AND f0.status = 1
              AND ISNULL(f0.is_signed_file, 0) = 0
          )
        )
      ORDER BY f.created_at
    `;

    const result = await request.query(sql);

    const filesMap: Record<string, any[]> = {};
    for (const row of result.recordset) {
      if (!filesMap[row.documentId]) filesMap[row.documentId] = [];
      filesMap[row.documentId].push(row);
    }

    return filesMap;
  }

