    const selectFields = ['outgoing_documents.*', ...dbKeys, ...extraFields].filter(Boolean).join(', ');
    // GROUP BY không được dùng cùng SELECT outgoing_documents.* (SQL Server sẽ báo lỗi 8120)
    // Vì JOIN audit có thể tạo duplicate row, ta dùng COUNT DISTINCT cho total.
    const countQuery = `
    SELECT COUNT(DISTINCT outgoing_documents.document_id) AS total
    FROM outgoing_documents
    ${joinClause}
    ${whereClause}
  `;

    const dataQuery = `
    SELECT ${selectFields}
    FROM outgoing_documents
    ${joinClause}
    ${whereClause}
    ${orderBy}
    OFFSET @offset ROWS FETCH NEXT @limit ROWS ONLY
  `;

    // Thực thi song song
