  async getAuthorizedNameMap(userIds: string[]): Promise<Map<string, string>> {
    const map = new Map<string, string>();
    if (!userIds || userIds.length === 0) return map;

    const query = `
      WITH RankedAuthority AS (
        SELECT author, authorized,
               ROW_NUMBER() OVER (PARTITION BY author ORDER BY start_date DESC) as rn
        FROM ${this.dbname}.dbo.authority_documents
        WHERE stage = '1'
          AND author IN (SELECT value FROM OPENJSON(@userIdsJson))
          AND start_date <= GETDATE()
          AND end_date >= GETDATE()
      )
      SELECT ra.author, ra.authorized, u.name as authorized_name
      FROM RankedAuthority ra
      LEFT JOIN ${this.dbname}.dbo.users u ON u.id = ra.authorized
      WHERE ra.rn = 1
    `;
    const result = await this.pool.request()
      .input('userIdsJson', JSON.stringify(userIds))
      .query(query);

    for (const row of result.recordset) {
      if (row.authorized_name) {
        map.set(row.author, row.authorized_name);
      }
    }
    return map;
  }

