  async createAuthority(dto: { authorized: string; startDate: Date; endDate: Date; files: string[] }, userId: string) {
    const query = `
      INSERT INTO ${this.dbname}.dbo.authority_documents
        (author, authorized, stage, status, start_date, end_date, original_end_date, files, created_at, updated_at)
      VALUES
        (@author, @authorized, '1', '1', @start_date, @end_date, @original_end_date, @files, GETDATE(), GETDATE());
      
      SELECT SCOPE_IDENTITY() AS id;
    `;
    const tx = await this.begin();

    try {
      // 1. Insert authority
      const result = await new Request(tx)
        .input('author', userId)
        .input('authorized', dto.authorized)
        .input('start_date', dto.startDate)
        .input('end_date', dto.endDate)
        .input('original_end_date', dto.endDate)
        .input('files', JSON.stringify(dto.files || []))
        .query(query);

      const authorityId = result.recordset?.[0]?.id;
      if (!authorityId) {
        throw new Error('Create authority failed');
      }

      // 2. Update user được ủy quyền
      await new Request(tx)
        .input('name_authorized', userId)
        .input('authorized', dto.authorized)
        .query(`
          UPDATE ${this.dbname}.dbo.users
          SET name_authorized = @name_authorized,
              updated_at = GETDATE()
          WHERE id = @authorized;
        `);

      // 3. Commit
      await this.commit(tx);

      return { id: authorityId };

    } catch (error) {
      await this.rollback(tx);
      console.error('SQL Error:', error);
      throw error;
    }
  }
  // Kiểm tra xung đột của người ủy quyền (author) - LOẠI TRỪ chính bản ghi đang sửa
