  async getAuthorIdIfAuthorized(userId: string): Promise<string | null> {
    if (!userId) return null;
    const now = Date.now();
    const cached = this.authorCache.get(userId);
    if (cached && cached.expiry > now) {
      return cached.value;
    }
    const query = `
      SELECT TOP 1 author
      FROM ${this.dbname}.dbo.authority_documents
      WHERE stage = '1'
        AND authorized = @userId
        AND start_date <= GETDATE()
        AND end_date >= GETDATE()
      ORDER BY start_date DESC
    `;
    const result = await this.pool.request()
      .input('userId', userId)
      .query(query);
    const value = result.recordset.length === 0 ? null : result.recordset[0].author;
    this.authorCache.set(userId, { value, expiry: now + 5000 }); // Cache for 5s
    return value;
  }


  async getAuthorAndAuthorizedName(userId: string): Promise<string | null> {
    if (!userId) return null;
    const query = `
      SELECT TOP 1 ad.author, ad.authorized, u.name AS authorized_name
      FROM ${this.dbname}.dbo.authority_documents ad
      INNER JOIN ${this.dbname}.dbo.users u ON ad.author = u.id
      WHERE ad.stage = '1'
        AND ad.authorized = @userId
        AND ad.start_date <= GETDATE()
        AND ad.end_date >= GETDATE()
      ORDER BY ad.start_date DESC
    `;
    const result = await this.pool.request()
      .input('userId', userId)
      .query(query);
    if (result.recordset.length === 0) {
      return null;
    }
    return result.recordset[0];
  }

  async buildDisplayNameWithAuthorized(
    targetUserId?: string | null,
  ): Promise<string> {
    if (!targetUserId) return '';
    let originalName = targetUserId;
    try {
      const name = await this.getNameOfUser(targetUserId);
      if (name) originalName = name;
    } catch {
      // ignore -> vẫn dùng originalName
    }

    try {
      const authorizedId = await this.getAuthorizedIdIfAuthor(targetUserId);
      if (!authorizedId || authorizedId === targetUserId) {
        return originalName;
      }
      let authorizedName = authorizedId;
      try {
        const name = await this.getNameOfUser(authorizedId);
        if (name) authorizedName = name;
      } catch {
        // ignore
      }
      return `${authorizedName} (được ${originalName} ủy quyền)`;
    } catch {
      return originalName;
    }
  }

