  async updateUnitStateTx(
    meetingId: string,
    userId: string,
    fromState: string,     // CONFIRMED
    toState: string,       // PROCESSING
    tx?: sql.Transaction,
  ): Promise<boolean> {
    const pool = tx ? null : await this.getPool();
    const executor = tx ? tx.request() : pool!.request();

    const result = await executor
      .input('meetingId', sql.UniqueIdentifier, meetingId)
      .input('userId', sql.VarChar, userId)
      .input('fromState', sql.VarChar, fromState)
      .input('toState', sql.VarChar, toState)
      .query(`
        ;WITH target_units AS (
          SELECT CAST(@userId AS nvarchar(100)) AS unit_id
          UNION
          SELECT parent
          FROM ${this.dbname}.dbo.users
          WHERE id = @userId
            AND parent IS NOT NULL
        )
        UPDATE mu
        SET mu.unit_state = @toState,
            mu.accept_join = 1
        FROM ${this.dbname}.dbo.meeting_units mu
        WHERE mu.meeting_id = @meetingId
          AND mu.unit_state = @fromState
          AND (
            mu.unit_id IN (SELECT unit_id FROM target_units)
            OR EXISTS (
              SELECT 1
              FROM ${this.dbname}.dbo.meeting_participants mp
              WHERE mp.meeting_unit_id = mu.id
                AND mp.user_type = 'UNIT'
                AND mp.unit_id IN (SELECT unit_id FROM target_units)
            )
          );
      `);

    return (result.rowsAffected?.[0] || 0) > 0;
  }


  // cập nhật trạng thái của phòng ban tham gia
  async updateMeetingUnitStateByUnitTx(
    meetingId: string,
    unitId: string,
    unitState: MEETING_UNIT_STATE,
    tx?: sql.Transaction,
  ): Promise<number> {
    const pool = tx ? null : await this.getPool();
    const executor = tx ? tx.request() : pool!.request();
    const result = await executor
      .input('meetingId', meetingId)
      .input('unitId', unitId)
      .input('unitState', unitState)
      .query(`
        UPDATE mu
        SET mu.unit_state = @unitState
        FROM ${this.dbname}.dbo.meeting_units mu
        LEFT JOIN ${this.dbname}.dbo.meetings m
          ON m.id = mu.meeting_id
        WHERE mu.meeting_id = @meetingId
          AND (
            mu.unit_id = @unitId
            OR (
              mu.unit_id = 'SECRETARY_UNIT'
              AND m.secretary_type = 'UNIT'
              AND m.secretary_id = @unitId
            )
          )
      `);

    return result.rowsAffected?.[0] || 0;
  }

