  // sqlRepo.mssql.ts
  async updateWorkItemNode(workItemId: string, nextNodeId: string, tx?: sql.Transaction) {
    const pool = tx ? null : await this.getPool();
    const executor = tx ? tx.request() : pool!.request();
    const now = new Date();

    // Cập nhật node_id và created_at nếu work item chưa ở node mới
    await executor
      .input('workItemId', workItemId)
      .input('nodeId', nextNodeId)
      .input('updatedAt', now)
      .query(`
        UPDATE ${this.dbname}.dbo.work_items WITH (ROWLOCK)
        SET node_id = @nodeId, created_at = @updatedAt
        WHERE id = @workItemId
      `);

    return true;
  }
