  // Lây thông tin người tạo để thu hồi 
  async getRecallTargetInfoTx(
    tx: sql.Transaction,
    meetingId: string,
  ): Promise<{
    targetNodeId: string;
    creatorUserId: string;
    creatorRole: string | null;
    creatorAuditId: number;
  }> {
    const result = await tx.request()
      .input('meetingId', meetingId)
      .query(`
        SELECT TOP 1
          a.id               AS creatorAuditId,
          a.from_node_id       AS targetNodeId,
          a.receiver         AS creatorUserId,
          a.role             AS creatorRole
        FROM ${this.dbname}.dbo.audit a
        WHERE
          a.document_id = @meetingId
          AND a.action_code = 'CREATE'
        ORDER BY a.created_at ASC
      `);

    if (!result.recordset?.length) {
      throw new Error('Không tìm thấy audit CREATE để thu hồi');
    }

    const row = result.recordset[0];

    if (!row.targetNodeId || !row.creatorUserId) {
      throw new Error('Thiếu thông tin node hoặc người tạo');
    }

    return {
      targetNodeId: row.targetNodeId,
      creatorUserId: row.creatorUserId,
      creatorRole: row.creatorRole,
      creatorAuditId: row.creatorAuditId,
    };
  }

