  async checkFollow(
    userId: string,
    documentId: string,
  ): Promise<boolean> {
    const pool = await this.pool; // mssql pool
    const request = pool.request();

    request.input('userId', userId);
    request.input('documentId', documentId);

    const query = `
      SELECT
        CASE
          WHEN EXISTS (
            SELECT 1
            FROM document_unfollow
            WHERE user_id = @userId
              AND document_id = @documentId
          )
          THEN CAST(1 AS BIT)
          ELSE CAST(0 AS BIT)
        END AS isFollow
    `;

    const result = await request.query<{ isFollow: boolean }>(query);

    return Boolean(result.recordset[0]?.isFollow);
  }
  async getMeeting(meetingId: string): Promise<any | null> {
    if (!meetingId) return null;

    const pool = await this.pool;
    const request = pool.request();
    request.input('meetingId', sql.UniqueIdentifier, meetingId);

    const query = `
      SELECT
        m.id,
        m.title,
        m.meeting_type AS meetingType,
        m.priority,
        m.meeting_date AS meetingDate,
        m.meeting_time AS meetingTime,
        m.meeting_mode AS meetingMode,
        m.room_ids AS roomIds,
        m.status,
        m.status_code AS statusCode,
        m.bpmn_version AS bpmnVersion,
        m.content,
        m.chairman_id AS chairmanId,
        m.secretary_id AS secretaryId,
        m.online_meeting_id AS onlineMeetingId,
        m.direct_command AS directCommand,
        m.created_at AS createdAt,
        m.created_by AS createdBy,
        m.updated_at AS updatedAt,
        m.need_confirmation AS needConfirmation
      FROM ${this.dbname}.dbo.meetings m
      WHERE m.id = @meetingId
    `;

    const result = await request.query(query);
    const meeting = result.recordset[0] || null;
    if (meeting && meeting.needConfirmation !== undefined) {
      meeting.needConfirmation = meeting.needConfirmation === true || meeting.needConfirmation === 1;
    }
    return meeting;
  }

