  // Cập nhật trạng thái cuộc họp
  async updateStatusMeetingRoom(
    meetingId: string,
    meetingState: MEETING_STATE,
    tx?: sql.Transaction,
  ): Promise<void> {
    const executor = tx ? tx.request() : this.pool.request();

    executor.input('meetingId', sql.UniqueIdentifier, meetingId);
    executor.input('meetingState', sql.VarChar, meetingState);

    await executor.query(`
      UPDATE mr
      SET
        mr.stage =
          CASE @meetingState
            WHEN 'DRAFT'        THEN 2
            WHEN 'DIEU_CHINH'   THEN 2
            WHEN 'DU_KIEN'      THEN 3
            WHEN 'CHUAN_BI'     THEN 3
            WHEN 'DANG_HOP'     THEN 4
            WHEN 'KET_THUC'     THEN 1
            WHEN 'DA_HUY'       THEN 1
            ELSE mr.stage
          END,
        mr.updated_at = GETDATE()
      FROM ${this.dbname}.dbo.meeting_rooms mr
      INNER JOIN ${this.dbname}.dbo.meetings m
        ON mr.id IN (
          SELECT LTRIM(RTRIM(value))
          FROM STRING_SPLIT(m.room_ids, ',')
        )
      WHERE m.id = @meetingId
    `);
  }
