  // Cập nhật trạng thái nghiệp vụ hồ sơ tiêu hủy
  async updateDestroyStatusCode(
    destroyId: string,
    statusCode: string,
    tx?: sql.Transaction,
  ): Promise<void> {

    // Kiểm tra UUID hợp lệ (basic check)
    if (!destroyId || typeof destroyId !== 'string') {
      throw new Error('destroyId không hợp lệ');
    }

    const executor = tx ? tx.request() : this.pool.request();

    executor.input('destroyId', sql.UniqueIdentifier, destroyId);
    executor.input('statusCode', sql.NVarChar(100), statusCode);

    const result = await executor.query(`
      UPDATE d
      SET 
        d.status_code = @statusCode,
        d.updated_at = SYSDATETIME()
      FROM ${this.dbname}.dbo.destroy_records d
      WHERE d.id = @destroyId
    `);

    if (!result.rowsAffected || result.rowsAffected[0] === 0) {
      throw new Error('Không tìm thấy hồ sơ tiêu hủy');
    }
  }
