  // Tìm người tạo hồ sơ khai thác
  async findCreatorId(
    documentId: string,
    tx?: sql.Transaction,
  ): Promise<string | null> {
    const executor = tx ? tx.request() : this.pool.request();

    executor.input('documentId', documentId);

    const rs = await executor.query(`
      SELECT TOP 1
        ISNULL(a.created_by, a.user_id) AS creator_id
      FROM ${this.dbname}.dbo.audit a
      WHERE a.document_id = @documentId
      ORDER BY a.id ASC
    `);

    if (!rs.recordset.length) {
      return null;
    }

    return rs.recordset[0].creator_id ?? null;
  }
