  /**
   * Lấy danh sách người ký từ bảng outgoing_document_users theo document_id và signer_type
   */
  async getSignersFromOutgoingDocumentUsers(
    documentId: string,
    signerType: string,
    is_signed?: number
  ): Promise<Array<{ user_id: string; sign_order: number }>> {

    const request = await this.getRequest();
    request.input('documentId', documentId);
    request.input('signerType', signerType);

    let sql = `
    SELECT user_id, sign_order, sign_key
    FROM ${this.dbname}.dbo.outgoing_document_users
    WHERE document_id = @documentId
      AND signer_type = @signerType
  `;

    if (is_signed !== undefined && is_signed !== null) {
      request.input('isSigned', is_signed);
      sql += ` AND is_signed = @isSigned`;
    } else {
      sql += ` AND is_signed = 0`;
    }

    // ORDER BY luôn ở cuối
    sql += ` ORDER BY sign_order ASC`;

    const result = await request.query(sql);
    return result.recordset || [];
  }

