  /**
   * Xóa toàn bộ reportSigner cũ và insert lại theo danh sách mới.
   * Chạy trong transaction nếu được truyền vào.
   */
  async replaceReportSigners(
    documentId: string,
    userIds: string[],
    tx?: Transaction,
  ): Promise<void> {
    const runner = tx ?? this.pool;

    await runner
      .request()
      .input('documentId', sql.VarChar, documentId)
      .query(`
        DELETE FROM outgoing_document_users
        WHERE document_id = @documentId
          AND signer_type = 'reportSigner'
          AND (is_signed = 0 OR is_signed IS NULL)
      `);

    if (!userIds.length) return;

    // Bulk insert bằng VALUES nhiều dòng để tránh N round-trips
    // Chỉ chèn những người chưa có trong DB (ví dụ bản ghi đã ký)
    const rows = userIds
      .map((_, i) => `(@documentId, @userId${i}, 'reportSigner', ${i + 1}, 0)`)
      .join(',\n');

    const req = runner.request().input('documentId', sql.VarChar, documentId);
    userIds.forEach((id, i) => req.input(`userId${i}`, sql.NVarChar, id));

    await req.query(`
      INSERT INTO outgoing_document_users
        (document_id, user_id, signer_type, sign_order, is_signed)
      SELECT d, u, t, o, s
      FROM (VALUES ${rows}) AS temp(d, u, t, o, s)
      WHERE NOT EXISTS (
        SELECT 1 FROM outgoing_document_users o2
        WHERE o2.document_id = temp.d 
          AND o2.user_id = temp.u 
          AND o2.signer_type = temp.t
      )
    `);
  }

