  async canAdditionalProcessingDocument(
    audit: any[],
    userId: string,
  ): Promise<boolean> {
    /** ===== Guard ===== */
    if (!Array.isArray(audit) || audit.length === 0) return false;
    if (!userId || typeof userId !== 'string') return false;

    /** ===== Các audit mà user là receiver ===== */
    const relatedAudits = audit.filter(a => a?.receiver === userId);
    if (relatedAudits.length === 0) return false;

    /** ===== Lấy documentId + danh sách createdBy ===== */
    let documentId: string | null = null;
    const createdByList: string[] = [];

    for (const a of relatedAudits) {
      if (documentId === null && a?.documentId !== undefined && a?.documentId !== null) {
        documentId = a.documentId;
      }

      if (a?.createdBy && a.createdBy !== userId) {
        createdByList.push(String(a.createdBy));
      }
    }

    if (!documentId || createdByList.length === 0) return false;

    /** ===== Comment hợp lệ ===== */
    const request = this.pool.request();
    request.input('documentId', documentId);

    const result = await request.query(`
      SELECT TOP 1 1
      FROM document_comments dc
      WHERE dc.document_id = @documentId
        AND dc.is_leader_suggestion = 1
    `);

    return result.recordset.length > 0;
  }
  async updateWorkitemAndAudit({ curNodeId, nodeId, userId }: { curNodeId?: string, nodeId: string, userId: string }): Promise<any> {
    const request = this.pool.request();
    request.input('curNodeId', curNodeId);
    request.input('node_id', nodeId);
    request.input('user_id', userId);

    await request.query(`
      UPDATE work_items 
      SET node_id = @node_id
      WHERE assignee_user_id = @user_id AND node_id = @curNodeId
    `);
    await request.query(`
      UPDATE audit
      SET from_node_id = @node_id
      WHERE user_id = @user_id
        AND from_node_id = @curNodeId
    `);

    return { success: true };
  }

