  /**
   * Kiểm tra xem người dùng hiện tại có phải là người ký chính thức cuối cùng của văn bản không.
   * Dùng để xác định thời điểm chèn [NgayVanBan] cho quy trình không đóng dấu (KY_SO_HS_K_DD).
   */
  async isFinalOfficialSigner(documentId: string, userId: string): Promise<boolean> {
    const request = this.pool.request();
    request.input('documentId', documentId);

    // Lấy danh sách tất cả người cần ký 'reportSigner' hoặc 'officialSigner1/2/3' mà chưa ký
    const result = await request.query(`
      SELECT user_id
      FROM outgoing_document_users
      WHERE document_id = @documentId
        AND signer_type IN ('reportSigner', 'officialSigner1', 'officialSigner2', 'officialSigner3')
        AND is_signed = 0
    `);

    const signersNotSigned = result.recordset || [];

    // Nếu chỉ còn 1 người chưa ký và người đó là userId hiện tại => Đây là người ký cuối cùng
    if (signersNotSigned.length === 1 && String(signersNotSigned[0].user_id) === String(userId)) {
      return true;
    }

    return false;
  }

  async checkAllUserSigned(documentId: string, typeSign: string, tx?: Transaction): Promise<boolean> {
    const runner = tx ?? this.pool;
    const request = runner.request();
    request.input('documentId', sql.VarChar(100), documentId);
    request.input('typeSign', sql.VarChar(100), typeSign);

    const result = await request.query(`
      SELECT COUNT(*) as total,
             SUM(CASE WHEN is_signed = 1 THEN 1 ELSE 0 END) as signedCount
      FROM ${this.dbname}.dbo.outgoing_document_users
      WHERE document_id = @documentId
        AND signer_type = @typeSign
    `);

    const { total, signedCount } = result.recordset[0] || { total: 0, signedCount: 0 };
    if (total === 0) return true; // No signers required, assume OK
    return total === signedCount;
  }

  async checkUserDocumentAuditAccess(
    documentId: string,
    userId: string,
    userUnit: string | null,
    roleCodes: string[],
  ): Promise<boolean> {
    const request = this.pool.request();
    request.input('documentId', documentId);
    request.input('userId', userId);

    const queryBranches = [
      `SELECT 1 AS x FROM ${this.dbname}.dbo.audit WHERE document_id = @documentId AND user_id = @userId`,
      `SELECT 1 AS x FROM ${this.dbname}.dbo.audit WHERE document_id = @documentId AND created_by = @userId`,
      `SELECT 1 AS x FROM ${this.dbname}.dbo.audit WHERE document_id = @documentId AND receiver = @userId`,
      `SELECT 1 AS x FROM ${this.dbname}.dbo.audit WHERE document_id = @documentId AND processed_by = @userId`,
      // Bổ sung quyền cho người được giao việc trong work_items (tránh lỗi 403 khi xin ý kiến phản hồi)
      `SELECT 1 AS x FROM ${this.dbname}.dbo.work_items WHERE document_id = @documentId AND assignee_user_id = @userId`,
      // Bổ sung quyền cho nhóm người xem văn bản đến
      `SELECT 1 AS x FROM ${this.dbname}.dbo.incomming_documents d CROSS APPLY STRING_SPLIT(d.view_group, ',') s INNER JOIN ${this.dbname}.dbo.group_users gu ON (gu.id = LTRIM(RTRIM(s.value)) OR gu.code = LTRIM(RTRIM(s.value))) INNER JOIN ${this.dbname}.dbo.user_group_users ugu ON ugu.group_user_id = gu.id WHERE d.document_id = @documentId AND ugu.user_id = @userId`,
      // Bổ sung quyền cho nhóm người xem văn bản đi
      `SELECT 1 AS x FROM ${this.dbname}.dbo.outgoing_documents od CROSS APPLY OPENJSON(od.document_viewer_groups) vg INNER JOIN ${this.dbname}.dbo.user_group_users ugu ON ugu.group_user_id = vg.value WHERE od.document_id = @documentId AND ugu.user_id = @userId AND ISJSON(od.document_viewer_groups) = 1`,
    ];

    if (userUnit && roleCodes && roleCodes.length > 0) {
      request.input('userUnit', userUnit);
      const roleParams = roleCodes.map((role, index) => {
        const paramName = `role_${index}`;
        request.input(paramName, role);
        return `@${paramName}`;
      }).join(', ');

      queryBranches.push(
        `SELECT 1 AS x FROM ${this.dbname}.dbo.audit WHERE document_id = @documentId AND receiver_unit = @userUnit AND role IN (${roleParams})`,
      );
    }

    const sqlQuery = `
      SELECT TOP 1 1 AS hasAccess
      FROM (
        ${queryBranches.join('\n        UNION ALL\n        ')}
      ) sub
    `;

    const result = await request.query(sqlQuery);
    return !!(result.recordset && result.recordset.length > 0);
  }

  async getOutgoingDocDetails(id: any): Promise<{ documentId: string | null; drafter: string | null }> {
    const idStr = String(id).trim();
    const numericId = Number(idStr);

    // Nếu là ID số và nằm trong phạm vi INT của SQL Server
    if (!isNaN(numericId) && Number.isInteger(numericId) && numericId >= -2147483648 && numericId <= 2147483647) {
      const result = await this.pool
        .request()
        .input('id', sql.Int, numericId)
        .query(`
          SELECT document_id, drafter
          FROM ${this.dbname}.dbo.outgoing_documents
          WHERE id = @id
        `);
      return {
        documentId: result.recordset?.[0]?.document_id ?? null,
        drafter: result.recordset?.[0]?.drafter ?? null,
      };
    } else {
      // Trường hợp id là UUID hoặc là số lớn (vượt quá INT) thì mapping với document_id
      const result = await this.pool
        .request()
        .input('documentId', sql.VarChar(100), idStr)
        .query(`
          SELECT document_id, drafter
          FROM ${this.dbname}.dbo.outgoing_documents
          WHERE document_id = @documentId
        `);
      return {
        documentId: result.recordset?.[0]?.document_id ?? null,
        drafter: result.recordset?.[0]?.drafter ?? null,
      };
    }
  }

